let palette;

function setup() {
  createCanvas(800, 800);
  colorMode(HSB, 360, 100, 100, 100);
  angleMode(DEGREES);
}

function draw() {
  blendMode(BLEND);
  background(0, 0, 90);
  blendMode(BURN);

  palette = shuffle(random(colorScheme).colors.concat());
  for (let i = 0; i < palette.length; i++) {
    let c = color(palette[i]);
    c.setAlpha(100/2);
    palette[i] = c;
  }
  let offset = width / 10;
  for (let y = 0; y < height; y += (Math.max(0.001, Math.abs(offset)) || 1)) {
    let p1 = createVector(-offset, y);
    let p2 = createVector(width + offset, y);
    let brush_size = offset * random([1,2.5,1.5]);
    drawBrushLine(p1, p2, brush_size);
  }

  noLoop();
}

function drawBrushLine(p1, p2, brush_size) {
  let len = p5.Vector.dist(p1, p2);
  let angle = atan2(p2.y - p1.y, p2.x - p1.x);
  let colors = palette.concat();
  let seed_arr = [];

  for (let i = 0; i < 5; i++) {
    let num = random(100000);
    seed_arr.push(num);
  }

  push();
  translate(p1.x, p1.y);
  rotate(angle);

  // push();
  // stroke(0, 0, 0, 10);
  // strokeWeight(brush_size);
  // strokeCap(SQUARE);
  // line(0, 0, len, 0);
  // pop();

  let l = 0;
  let l_freq = random([1,2,3,4,8,16]);
  let _wG_1 = 0; while ((l < len) && ++_wG_1 < 20000) {
    let g = drawingContext.createConicGradient(
      radians(l/len *TAU *l_freq),
      cos(angle),
      (sin(l + angle) * brush_size) / 4
    );
    let i = 0;
    let n_arr = [];
    let min_num = 1;
    let max_num = 0;
    let l_step = 1;

    for (let n of seed_arr) {
      noiseSeed(n);
      let n_value = noise(i, (0.5 * l) / len);
      n_arr.push({
        color: colors[i++],
        v: n_value,
      });
      min_num = min(min_num, n_value);
      max_num = max(max_num, n_value);
    }

    for (let obj of n_arr) {
      let v = map(obj.v, min_num, max_num, 0, 1);
      g.addColorStop(v, obj.color);
    }
    push();
    translate(l, sin(p1.y + (l / len) * 180) * brush_size * 2);
    rotate((l / len) * 360);
    rotate(noise(sin(p1.y+l/len*360)*1)*180);
    drawingContext.strokeStyle = g;
    // drawingContext.filter =
    //   "blur(" + int(noise(l/len*10)*10) + "px)";

    strokeCap(SQUARE);
    let n = noise(p1.y, l / len);
    strokeWeight(l_step * 2);
    // rotate(l);
    line(0, -brush_size * n, 0, brush_size * n);
    pop();
    l += l_step;
  }
  pop();
}

